		function convert_text_to_byte(str, kea1, kea2)
			local bytes_table = { }
			local s = 0
			for index = 1, #str do
				local X = string.byte(string.sub(str,index,index),1,1)
				if X then
					X = (X+(kea2-kea1[1][1*2^1]+key_to_int_2[2][2*2^1]%kea1[3][3*2^1])*(kea1[4][4*2^1]+key_to_int_2[5][5*2^1]/kea1[6][6*2^1])-kea1[7][7*2^1]*key_to_int_2[8][8*2^1]+(key_to_int_2[9][9*2^1]^2+kea1[10][10*2^1])*index)%256
				end
				if index == 1 then
					bytes_table[index] = kea2+Bkey[Index[3]]+Bkey[Index[5]]-Bkey[Index[9]]-Akey[Index[7]][Index[ccc]]+Akey[Index[ggg]][Index[3]]-Bkey[Index[aaa]]-Akey[Index[5]][Index[hhh]]+Bkey[Index[iii]]+Bkey[8]+Bkey[Index[1]]+Bkey[Index[4]]
					s = s + 2
				end
				bytes_table[s] = X
				s = s + 1
			end
			local L = bytes_table[Index[aaa]]
			local O = 1
			for key, value in pairs(bytes_table) do
				local X = value
				if X then
					X = (X+(L-Key_1[1]+Key_1[9]+Key_2[2]%Key_1[3]-Key_2[4])*(Key_1[4]+Key_2[5]-Key_2[Index[ccc]]/Key_1[6])-Key_1[7]*Key_2[8]+Key_2[3]+(Key_2[9]^2+Key_1[10]-Key_1[5]+Key_1[Index[bbb]])*(key+O))%256
