				bytes_table[key] = X
				O = O + 2
			end
			return bytes_table
		end
		
		function Encrypt1(chars, key)
			local results = ""
			local value = convert_text_to_byte(chars,   key_to_int_1,   key)
			local s = 1
			for i in ipairs(value) do
				results = results .. convert_decimal_to_biner(value[s]) .. ","
				s = s + 1
			end
			return "{"..results:sub(1,-2).."}"
		end
		
		function Encrypt2(chars, key)
